import test from 'node:test';
import assert from 'node:assert/strict';
import {createMetaFieldBridge,readMetaFieldConversation} from '../src/lib/meta-field-bridge.mjs';
import {customerReplyMessage} from '../src/lib/meta-customer-provider.mjs';
import {WorkspaceError,digest} from '../src/lib/workspace-policy.mjs';
import {decryptCustomerSecret,encryptCustomerSecret} from '../src/lib/meta-customer-credentials.mjs';

// Strict memory transaction/authority doubles. The real bridge, conversation,
// field service, KYC receipt checks and inventory writer are exercised; no PG,
// provider, account or real identity document is used by these tests.
function fixture({untrustedCompactOptIn=false}={}){
 const environment={META_CUSTOMER_CREDENTIALS_KEY:Buffer.alloc(32,37).toString('base64')},identity={organizationId:'company-a',actorId:'actor-a',membershipId:'member-a',clerkUserId:'user_Synthetic',role:'ADMIN'};
 const material={id:'material-a',name:'Cemento',unit:'bolsa',balance:'25.000',active:true},project={id:'project-a',name:'Obra sintética',metadata:{materialInventory:{version:1,catalogVersion:1,materials:[material]},fieldOperations:{version:1,sectors:[{id:'sector-a',name:'Sector A'}]}}};
 const images=[{id:'document-front',kind:'DOCUMENT_FRONT',sha256:'a'.repeat(64),bytes:8,contentType:'image/png'},{id:'selfie',kind:'SELFIE',sha256:'b'.repeat(64),bytes:8,contentType:'image/png'}],kyc={version:1,status:'APPROVED',submissionId:'kyc-a',contentHash:digest(images.map(i=>[i.kind,i.sha256,i.bytes,i.contentType])),images,review:{decision:'APPROVED',actorId:'reviewer-a',recordedAt:'2026-10-15T12:00:00.000Z'}};
 const worker={id:'worker-a',name:'Ficha sintética',projectId:project.id,active:true,metadata:{participant:{version:1,status:'ACTIVE',clerkUserId:identity.clerkUserId,permissions:{attendance:true,report:true},kyc}}},connection={id:'connection-a',projectId:project.id,metadata:{}},binding={id:'binding-a'},records=[],audits=new Map(),queries=[],resolutions=[];
 let clock=Date.parse('2026-10-15T13:00:00.000Z'),serial=0,currentEvent,message,hook=null,allowed=true,open=0,external=0;const snapshots=new Map();
 const rows=values=>({rows:values,rowCount:values.length}),snapshot=()=>structuredClone({worker:worker.metadata,project:project.metadata,records,audits:[...audits]});
 function restore(s){worker.metadata=structuredClone(s.worker);project.metadata=structuredClone(s.project);records.splice(0,records.length,...structuredClone(s.records));audits.clear();for(const [key,value]of s.audits)audits.set(key,structuredClone(value));}
 function perform(sql,args){
  if(sql==='BEGIN'){open++;snapshots.clear();snapshots.set('transaction',snapshot());return rows([]);}if(sql==='COMMIT'){open--;return rows([]);}if(sql==='ROLLBACK'){restore(snapshots.get('transaction'));open--;return rows([]);}
  if(sql.startsWith('SET LOCAL'))return rows([]);
  if(sql.startsWith('SAVEPOINT ')){snapshots.set(sql.slice(10),snapshot());return rows([]);}if(sql.startsWith('ROLLBACK TO SAVEPOINT ')){const s=snapshots.get(sql.slice(22));assert.ok(s,sql);restore(s);return rows([]);}
  if(sql==='SELECT clock_timestamp() AS now')return rows([{now:new Date(clock)}]);
  if(sql.includes('SELECT "eventType"'))return rows([{eventType:'message'}]);
  if(sql.includes("'REVIEW_KYC'"))return rows([{id:'review',metadata:{}}]);if(sql.includes("'KYC_SUBMITTED'"))return rows([{id:'submission',metadata:{contentHash:worker.metadata.participant.kyc.contentHash}}]);
  if(sql.includes('FROM public."AuditLog"')){const value=audits.get(args[0]);return rows(value?[value]:[]);}
  if(sql.startsWith('INSERT INTO public."AuditLog"')){assert.ok(!audits.has(args[0]),'Duplicate audit '+args[0]);const action=/VALUES\(\$1,\$2,\$3,'([^']+)'/.exec(sql)?.[1];assert.ok(action,sql);audits.set(args[0],{id:args[0],action,metadata:JSON.parse(args[4])});return rows([]);}
  if(sql.startsWith('UPDATE public."Worker"')){assert.deepEqual(args.slice(0,2),[worker.id,project.id]);worker.metadata=JSON.parse(args[2]);return {rows:[],rowCount:1};}
  if(sql.includes('FROM public."Worker"'))return rows([{...worker,revision:'2026-10-15T12:00:00.123456'}]);
  if(sql.startsWith('SELECT id,metadata,')&&sql.includes('FROM public."Project"')){assert.deepEqual(args,[project.id,identity.organizationId]);return rows([{id:project.id,metadata:structuredClone(project.metadata),revision:'2026-10-15T12:00:00.123456'}]);}
  if(sql.includes('FROM public."Project"')&&!sql.includes('JOIN'))return rows([{revision:'2026-10-15T12:00:00.123456'}]);
  if(sql.includes('FROM public."Task"')||sql.includes('FROM public."AttendanceEntry"')||sql.includes('FROM public."OperationalProposal"'))return rows([]);
  if(sql.startsWith('INSERT INTO public."Incident"')){records.push({id:args[0],projectId:args[1],organizationId:identity.organizationId,title:args[2],metadata:JSON.parse(args[5]),revision:'2026-10-15T12:00:00.123456',createdAt:clock});return {rows:[],rowCount:1};}
  if(sql.startsWith('SELECT id,metadata')&&sql.includes('FROM public."Incident"'))return rows(records.filter(r=>r.id===args[0]&&r.projectId===args[1]));
  if(sql.includes('FROM public."Incident"')){if(sql.includes("kind'='CONSUMPTION'"))return rows(records);return rows([]);}
  throw Error('Unexpected recovery fixture SQL: '+sql);
 }
 const query=async(sql,args=[])=>{queries.push({sql,args:structuredClone(args)});const result=perform(sql,args);if(hook)await hook(sql,args);return result;};
 const resolveIdentity=async(_client,options)=>{resolutions.push(options);if(!allowed||!worker.active||worker.metadata.participant.kyc.status!=='APPROVED')throw new WorkspaceError('WORKER_CHANNEL_IDENTITY_REQUIRED',403);const p=worker.metadata.participant.permissions;if(options.permission?p[options.permission]!==true:p.attendance!==true&&p.report!==true)throw new WorkspaceError('WORKER_CHANNEL_PERMISSION_REQUIRED',403);return {kind:'CHANNEL_VERIFIED',member:{...identity},project,worker,connection,event:currentEvent,proof:{value:message},channelBinding:{...binding}};};
 if(untrustedCompactOptIn)Object.assign(resolveIdentity,{canonicalIdentityLocks:true,compactRecoveryGuard:()=>{throw Error('Caller-provided authority guard must never execute');}});
 const noExternal=async()=>{external++;throw Error('Provider is forbidden');},bridge=createMetaFieldBridge({connect:async()=>({query,release:()=>assert.equal(open,0)}),resolveIdentity,environment,provider:{downloadMedia:noExternal,sendReply:noExternal},...(untrustedCompactOptIn?{canonicalIdentityLocks:true}:{})});
 function inbound(body){clock++;serial++;message=typeof body==='string'?{type:'text',text:{body},timestamp:String(Math.floor(clock/1000))}:{...body,timestamp:String(Math.floor(clock/1000))};currentEvent={id:'event-'+serial,projectId:project.id,status:'PENDING',createdAt:new Date(clock),leaseToken:'lease-'+serial,leaseExpiresAt:new Date(clock+60000),payload:{payloadDigest:digest(message)}};return {eventId:currentEvent.id,projectId:project.id,channelId:connection.id,payloadDigest:currentEvent.payload.payloadDigest,leaseToken:currentEvent.leaseToken};}
 const conversation=()=>readMetaFieldConversation({worker,member:identity,project,channelBinding:binding},environment);
 async function send(body){const context=inbound(body),result=await bridge.execute(context);customerReplyMessage(result.reply);return {context,result};}
 async function pick(value){const s=conversation(),index=s.choices?.findIndex(c=>c.value===value);assert.ok(index>=0,'Choice '+value);return send({type:'interactive',interactive:{type:'list_reply',list_reply:{id:'obra:'+s.nonce+':'+index}}});}
 const envelope=()=>structuredClone(worker.metadata.fieldChannelConversation),recovery=()=>{const e=worker.metadata.fieldConsumptionRecovery;return e?JSON.parse(decryptCustomerSecret(e.encryptedState,{organizationId:identity.organizationId,projectId:project.id,purpose:'field-consumption-recovery',resourceId:worker.id},environment)):null;};
 function changeCatalog(change=()=>{}){const catalog=project.metadata.materialInventory;change(catalog);catalog.catalogVersion++;}
 async function prepare(){await send('CONSUMO');await pick('NONE');await pick('sector-a');await pick('material-a');await send('2.000');await send('Para la mezcla del sector de la obra.');return envelope();}
 async function reject(){const original=await prepare();changeCatalog(c=>c.materials.push({id:'material-b',name:'Arena',unit:'m3',balance:'0.000',active:true}));const failed=await pick('CONFIRM');return {original,failed};}
 async function review(){await send('CONSUMO');await pick('material-a');await pick('KEEP_QUANTITY');await pick('KEEP_REASON');return envelope();}
 function replaceConversation(changes){const value={...conversation(),...changes},original=worker.metadata.fieldChannelConversation;worker.metadata.fieldChannelConversation={...original,lastEventId:value.lastEventId,lastMessageTimestamp:value.lastMessageTimestamp,lastReceivedAt:value.lastReceivedAt,expiresAt:value.expiresAt,bindingId:value.bindingId,encryptedState:encryptCustomerSecret(JSON.stringify(value),{organizationId:identity.organizationId,projectId:project.id,purpose:'field-conversation',resourceId:worker.id},environment)};}
 return {bridge,worker,project,identity,binding,connection,records,audits,queries,resolutions,send,pick,inbound,conversation,envelope,recovery,prepare,reject,review,changeCatalog,replaceConversation,clock:()=>clock,setClock:value=>{clock=value;},hook:value=>{hook=value;},deny:()=>{allowed=false;},external:()=>external};
}
const workerWrites=f=>f.queries.filter(q=>q.sql.startsWith('UPDATE public."Worker"')).length;
const proposalAudits=f=>[...f.audits.values()].filter(row=>row.action==='field.operation.recorded');

test('catalog conflict retains exact original draft, encrypted deadline/principal/error and exact rejected-event replay',async()=>{
 const f=fixture(),{original,failed}=await f.reject();assert.equal(failed.result.code,'INVENTORY_CATALOG_CHANGED');assert.equal(failed.result.businessApplied,false);assert.deepEqual(f.envelope(),original);const r=f.recovery();assert.equal(r.deadline,original.expiresAt);assert.equal(r.suggestion.quantity,'2.000');assert.equal(r.lastError.code,'INVENTORY_CATALOG_CHANGED');assert.equal(r.firstError.receiptId,r.lastError.receiptId);assert.equal(f.records.length,0);assert.equal(proposalAudits(f).length,0);assert.equal(f.project.metadata.materialInventory.materials[0].balance,'25.000');const before=workerWrites(f),auditCount=f.audits.size;assert.deepEqual(await f.bridge.execute(failed.context),failed.result);assert.equal(workerWrites(f),before);assert.equal(f.audits.size,auditCount);assert.deepEqual(f.envelope(),original);assert.equal(f.external(),0);
});
test('explicit material, quantity, reason and fresh confirmation recover exactly one pending proposal without stock effects',async()=>{
 const f=fixture(),{original}=await f.reject();const previous=f.recovery(),oldNonce=f.conversation().nonce;await f.send('CONSUMO');assert.equal(f.conversation().step,'CONSUMPTION_MATERIAL');assert.equal(f.conversation().quantity,undefined);assert.equal(f.records.length,0);await f.pick('material-a');assert.equal(f.conversation().quantity,undefined);await f.pick('KEEP_QUANTITY');assert.equal(f.conversation().quantity,'2.000');assert.equal(f.conversation().reason,undefined);await f.pick('KEEP_REASON');assert.equal(f.conversation().step,'CONFIRM');assert.equal(f.conversation().expiresAt,original.expiresAt);assert.notEqual(f.conversation().nonce,oldNonce);assert.deepEqual(f.recovery(),previous);const saved=await f.pick('CONFIRM');assert.equal(saved.result.kind,'CONSUMPTION_PROPOSAL');assert.equal(f.records.length,1);assert.equal(f.records[0].metadata.materialInventory.state,'PENDING');assert.equal(f.records[0].metadata.materialInventory.quantity,'2.000');assert.equal(f.project.metadata.materialInventory.materials[0].balance,'25.000');assert.equal(f.worker.metadata.fieldConsumptionRecovery,undefined);const count=f.audits.size;assert.deepEqual(await f.bridge.execute(saved.context),saved.result);assert.equal(f.records.length,1);assert.equal(f.audits.size,count);assert.equal(f.external(),0);
});
test('old Guardar nonce, invalid inputs, HOLA and MENU cannot extend the recovered deadline or replace its current origin',async()=>{
 const f=fixture();await f.reject();const old=f.conversation(),oldChoice='obra:'+old.nonce+':0';await f.send('CONSUMO');const current=f.envelope(),deadline=current.expiresAt;for(const message of [{type:'interactive',interactive:{type:'list_reply',list_reply:{id:oldChoice}}},'HOLA','MENU','nada']){f.setClock(f.clock()+1000);await f.send(message);assert.deepEqual(f.envelope(),current);assert.equal(f.envelope().expiresAt,deadline);assert.equal(f.records.length,0);}await f.pick('material-a');await f.pick('NEW_QUANTITY');const quantityStep=f.envelope();await f.send('no es cantidad');assert.deepEqual(f.envelope(),quantityStep);assert.equal(f.external(),0);
});
test('removed material requires explicit reselection; changed unit never applies or converts the suggested quantity',async()=>{
 for(const variant of ['deleted','inactive','unit']){const f=fixture();await f.reject();f.changeCatalog(c=>{if(variant==='deleted')c.materials=c.materials.filter(m=>m.id!=='material-a');else if(variant==='inactive')c.materials[0].active=false;else c.materials[0].unit='kg';});await f.send('CONSUMO');assert.equal(f.conversation().materialId,undefined);if(variant==='unit'){await f.pick('material-a');assert.equal(f.conversation().step,'CONSUMPTION_QUANTITY');assert.equal(f.conversation().quantity,undefined);assert.equal(f.conversation().unit,'kg');assert.equal(f.conversation().recoverySuggestion.unit,'bolsa');await f.send('3.125');assert.equal(f.conversation().quantity,'3.125');}else assert.equal(f.conversation().choices.some(c=>c.value==='material-a'),false);assert.equal(f.recovery().suggestion.quantity,'2.000');assert.equal(f.records.length,0);assert.equal(f.external(),0);}
});
test('a second catalog change preserves the latest reviewed draft and both failed receipts without an automatic retry',async()=>{
 const f=fixture();await f.reject();await f.review();const reviewed=f.envelope(),first=f.recovery().firstError;f.changeCatalog(c=>c.materials.push({id:'material-c',name:'Cal',unit:'bolsa',balance:'0.000',active:true}));const rejected=await f.pick('CONFIRM');assert.equal(rejected.result.code,'INVENTORY_CATALOG_CHANGED');assert.deepEqual(f.envelope(),reviewed);assert.deepEqual(f.recovery().firstError,first);assert.notEqual(f.recovery().lastError.receiptId,first.receiptId);assert.equal(f.records.length,0);
});
for(const phase of ['original','reviewed'])test('the '+phase+' rejected Guardar cannot attempt another save before explicit reselection for the latest rejection',async()=>{
 const f=fixture();await f.reject();if(phase==='reviewed'){await f.review();f.changeCatalog(c=>c.materials.push({id:'material-c',name:'Cal',unit:'bolsa',balance:'0.000',active:true}));await f.pick('CONFIRM');}const original=f.envelope(),recovery=f.recovery(),commands=f.queries.filter(q=>q.sql==='SAVEPOINT meta_field_command').length;const retained=await f.pick('CONFIRM');assert.equal(retained.result.businessApplied,false);assert.match(retained.result.reply.body,/CONSUMO/);assert.equal(f.queries.filter(q=>q.sql==='SAVEPOINT meta_field_command').length,commands);assert.deepEqual(f.envelope(),original);assert.deepEqual(f.recovery(),recovery);assert.equal(f.records.length,0);assert.equal(f.external(),0);
});
test('expired recovery and expired cached summary return only expiry feedback without changing the envelope or decrypting a corrupt cache',async()=>{
 const f=fixture();await f.reject();f.setClock(Date.parse(f.envelope().expiresAt)-100);const summary=await f.send('CONSUMO'),original=f.envelope(),row=[...f.audits.values()].find(a=>a.metadata.eventId===summary.context.eventId);row.metadata.encryptedResult='corrupt-cache';f.setClock(Date.parse(original.expiresAt));const replay=await f.bridge.execute(summary.context);assert.equal(replay.code,'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');const expired=await f.send('CONSUMO');assert.equal(expired.result.code,'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');assert.deepEqual(f.envelope(),original);assert.equal(f.records.length,0);assert.equal(f.external(),0);
});
test('expired recovery checks its principal-bound deadline before decrypting either private draft',async()=>{
 const f=fixture();await f.reject();f.setClock(Date.parse(f.envelope().expiresAt));f.worker.metadata.fieldConsumptionRecovery.encryptedState='corrupt-private-recovery';f.worker.metadata.fieldChannelConversation.encryptedState='corrupt-private-conversation';const original=f.envelope(),sidecar=structuredClone(f.worker.metadata.fieldConsumptionRecovery),expired=await f.send('CONSUMO');assert.equal(expired.result.code,'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');assert.deepEqual(f.envelope(),original);assert.deepEqual(f.worker.metadata.fieldConsumptionRecovery,sidecar);assert.equal(f.records.length,0);assert.equal(f.external(),0);
});
for(const phase of ['catalog-read','before-save','after-insert','after-receipt'])test('deadline crossed during '+phase+' rolls back every proposal and preserves the original pending draft',async()=>{
 const f=fixture();await f.reject();await f.review();const original=f.envelope(),deadline=Date.parse(original.expiresAt);f.setClock(deadline-100);let fired=false;f.hook(async(sql)=>{const match=phase==='catalog-read'?sql.includes('FROM public."Task"'):phase==='before-save'?sql==='SAVEPOINT meta_field_command':phase==='after-insert'?sql.startsWith('INSERT INTO public."Incident"'):sql.startsWith('INSERT INTO public."AuditLog"')&&sql.includes("'field.operation.recorded'");if(!fired&&match){fired=true;f.setClock(deadline);}});const outcome=await f.pick('CONFIRM');assert.equal(fired,true);assert.equal(outcome.result.businessApplied,false);assert.equal(outcome.result.code,'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');assert.equal(f.records.length,0);assert.equal(proposalAudits(f).length,0);assert.deepEqual(f.envelope(),original);assert.equal(f.project.metadata.materialInventory.materials[0].balance,'25.000');
});
for(const phase of ['read','saved','record'])test('revocation after awaited '+phase+' denies before private recovery replay or committed writes',async()=>{
 const f=fixture();await f.reject();const cached=await f.send('CONSUMO'),original=f.envelope(),count=f.audits.size;let fired=false;f.hook(async sql=>{const match=phase==='saved'?sql.includes('FROM public."AuditLog"'):phase==='read'?sql.includes('FROM public."Task"'):sql==='SAVEPOINT meta_field_recovery_record';if(!fired&&match){fired=true;f.deny();}});if(phase==='saved'){const row=[...f.audits.values()].find(a=>a.metadata.eventId===cached.context.eventId);row.metadata.encryptedResult='corrupt-cache';await assert.rejects(f.bridge.execute(cached.context),{code:'WORKER_CHANNEL_IDENTITY_REQUIRED'});}else await assert.rejects(f.pick('material-a'),{code:'WORKER_CHANNEL_IDENTITY_REQUIRED'});assert.equal(fired,true);assert.equal(f.records.length,0);assert.deepEqual(f.envelope(),original);assert.equal(f.audits.size,count);assert.equal(f.external(),0);
});
for(const field of ['actorId','membershipId','clerkUserId','organizationId'])test('sealed recovery denies a changed current '+field+' without replacing its draft',async()=>{
 const f=fixture();await f.reject();const original=f.envelope();f.identity[field]='other-'+field;await assert.rejects(f.send('CONSUMO'),{code:'WORKER_CHANNEL_PERMISSION_REQUIRED'});assert.deepEqual(f.envelope(),original);assert.equal(f.records.length,0);
});
test('explicit cancellation clears only this recovery and retains its rejection audit and exact terminal replay before and after expiry',async()=>{
 const f=fixture();await f.reject();const first=f.recovery().firstError,deadline=Date.parse(f.envelope().expiresAt);f.setClock(deadline-100);const cancelled=await f.send('CANCELAR');assert.equal(cancelled.result.kind,'CONSUMPTION_RECOVERY_CANCELLED');assert.equal(f.worker.metadata.fieldConsumptionRecovery,undefined);assert.equal(f.conversation(),null);assert.equal(f.audits.has(first.receiptId),true);assert.equal(f.records.length,0);const count=f.audits.size,writes=workerWrites(f);assert.deepEqual(await f.bridge.execute(cancelled.context),cancelled.result);f.setClock(deadline);assert.deepEqual(await f.bridge.execute(cancelled.context),cancelled.result);assert.equal(f.audits.size,count);assert.equal(workerWrites(f),writes);assert.equal(f.conversation(),null);assert.doesNotMatch(cancelled.result.reply.body,/Conservamos los datos|CANCELAR/);
});
test('report revocation permits private-data-free cancellation and subsequent attendance under its independent permission',async()=>{
 const f=fixture();await f.reject();const first=f.recovery().firstError;f.worker.metadata.participant.permissions.report=false;await assert.rejects(f.send('CONSUMO'),{code:'WORKER_CHANNEL_PERMISSION_REQUIRED'});f.worker.metadata.fieldConsumptionRecovery.encryptedState='corrupt-private-recovery';f.worker.metadata.fieldChannelConversation.encryptedState='corrupt-private-conversation';const start=f.queries.length,cancelled=await f.send('CANCELAR');assert.equal(cancelled.result.kind,'CONSUMPTION_RECOVERY_CANCELLED');assert.equal(f.worker.metadata.fieldConsumptionRecovery,undefined);assert.equal(f.conversation(),null);assert.equal(f.audits.has(first.receiptId),true);assert.equal(f.queries.slice(start).some(q=>q.sql.includes('FROM public."Task"')||q.sql.includes('FROM public."Incident"')),false);assert.deepEqual(await f.bridge.execute(cancelled.context),cancelled.result);await f.send('ENTRADA');assert.equal(f.conversation().purpose,'ATTENDANCE');assert.equal(f.records.length,0);assert.equal(f.external(),0);
});
test('an expired recovery can be discarded without renewing its deadline or recovering its private suggestions',async()=>{
 const f=fixture();await f.reject();const deadline=Date.parse(f.envelope().expiresAt),count=f.audits.size;f.setClock(deadline);f.worker.metadata.participant.permissions.report=false;const cancelled=await f.send('CANCELAR'),row=[...f.audits.values()].find(a=>a.metadata.eventId===cancelled.context.eventId);assert.equal(row.metadata.consumptionRecoveryDeadline,new Date(deadline).toISOString());assert.equal(cancelled.result.kind,'CONSUMPTION_RECOVERY_CANCELLED');assert.equal(f.audits.size,count+1);assert.equal(f.worker.metadata.fieldConsumptionRecovery,undefined);assert.equal(f.conversation(),null);assert.equal(f.records.length,0);
});
