 const f=fixture();await f.reject();f.worker.metadata.participant.permissions.report=false;let cached;if(phase==='saved')cached=await f.send('CANCELAR');const original=f.envelope(),count=f.audits.size;let fired=false;f.hook(async sql=>{if(!fired&&(phase==='saved'?sql.includes('FROM public."AuditLog"'):sql.startsWith('UPDATE public."Worker"'))){fired=true;f.deny();}});if(cached)await assert.rejects(f.bridge.execute(cached.context),{code:'WORKER_CHANNEL_IDENTITY_REQUIRED'});else await assert.rejects(f.send('CANCELAR'),{code:'WORKER_CHANNEL_IDENTITY_REQUIRED'});assert.equal(fired,true);assert.deepEqual(f.envelope(),original);assert.equal(f.audits.size,count);assert.equal(f.records.length,0);assert.equal(f.external(),0);
