 assert.deepEqual(await f.bridge.execute(context),result);assert.equal(f.writes.length,count);assert.equal(f.queries.some(q=>q.sql.includes('FROM public."Task"')),false,'Router withdrawal need not decrypt or enter FIELD service');assert.equal(f.external(),0);
